#!/usr/bin/env bash
#
# Builds the documentation site:
#   1. renders the Markdown pages under docs/ to HTML with the site template;
#   2. copies the API reference already generated by Doxygen.
#
# Usage: docs/build-docs.sh [output-directory]        (default build/site)
#
# The reference comes from CMake, so it has to be generated first:
#
#   cmake -S . -B build -DOPENANIMA_ENABLE_DOCS=ON
#   cmake --build build --target docs
#   docs/build-docs.sh
#
# Paths can be overridden with environment variables:
#
#   PANDOC=/path/to/pandoc API_SRC=/path/to/html docs/build-docs.sh
#
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DOCS="$ROOT/docs"
OUT="${1:-$ROOT/build/site}"
API_SRC="${API_SRC:-$ROOT/build/docs/html}"
PANDOC="${PANDOC:-pandoc}"

command -v "$PANDOC" >/dev/null 2>&1 ||
  { echo "ERROR: '$PANDOC' not found. Install it from: https://pandoc.org/installing.html" >&2; exit 1; }

PANDOC_COMMON=(
  --from gfm
  --to html5
  --standalone
  --metadata lang=en
  --template "$DOCS/site/template.html"
  --css style.css
  # Newer pandoc versions call this --syntax-highlighting and warn about the old
  # name. The old name is the one the pandoc in the CI image understands.
  --highlight-style tango
)

echo "==> Site: $OUT"
rm -rf "$OUT"
mkdir -p "$OUT/api"

cp "$DOCS"/site/style.css "$OUT/style.css"
touch "$OUT/.nojekyll"

echo "==> Pages: pandoc"
for src in "$DOCS"/*.md; do
  name="$(basename "${src%.md}")"
  # The first heading is the title of the page.
  title="$(sed -n '1s/^# \{0,1\}//p' "$src")"

  # The landing page is short enough to be read without an index on the side.
  extra=()
  if [ "$name" != "index" ]; then
    extra=(--toc --toc-depth=2)
  fi

  echo "    ${name}.md -> ${name}.html"
  "$PANDOC" "$src" "${PANDOC_COMMON[@]}" ${extra[@]+"${extra[@]}"} \
    --metadata title="$title" -o "$OUT/${name}.html"
done

if [ -d "$API_SRC" ]; then
  echo "==> API reference: $API_SRC -> $OUT/api"
  cp -r "$API_SRC"/. "$OUT/api/"
else
  echo "==> WARNING: no API reference in $API_SRC"
  echo "    generate it with: cmake --build build --target docs"
  cat > "$OUT/api/index.html" <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>API reference pending</title>
<link rel="stylesheet" href="../style.css">
</head>
<body>
<main class="wrap"><article class="doc">
<h1>API reference pending</h1>
<p>The reference has not been generated yet. It is built by Doxygen, through CMake:</p>
<pre><code>cmake -S . -B build -DOPENANIMA_ENABLE_DOCS=ON
cmake --build build --target docs
docs/build-docs.sh</code></pre>
<p><a href="../index.html">Back to the start</a></p>
</article></main>
</body>
</html>
EOF
fi

echo
echo "Done. To preview it locally:"
echo "  python3 -m http.server -d $OUT 8000     # http://localhost:8000"
